public function workspace(string$id,?string$org,bool$platform):array{if(!$this->accessible($id,$org,$platform)){return['assignment'=>null,'notes'=>[]];}$assignment=$this->db->get_row($this->db->prepare("SELECT a.*,u.display_name,u.user_email FROM `{$this->a}` a LEFT JOIN `{$this->db->users}` u ON u.ID=a.reviewer_user_id WHERE a.resource_version_id=%s",$id),ARRAY_A);$notes=$this->db->get_results($this->db->prepare("SELECT n.*,u.display_name FROM `{$this->n}` n LEFT JOIN `{$this->db->users}` u ON u.ID=n.author_user_id WHERE n.resource_version_id=%s ORDER BY n.created_at DESC",$id),ARRAY_A);return['assignment'=>is_array($assignment)?$assignment:null,'notes'=>is_array($notes)?$notes:[]];}
